import { Router } from "express";
import { asyncHandler } from "../../../shared/http/async-handler.js";
import { ensureAuthenticated, ensurePermissions } from "../../auth/middlewares/auth.middleware.js";
import { DashboardController } from "../controllers/dashboard.controller.js";
const controller = new DashboardController();
export const dashboardRoutes = Router();
dashboardRoutes.get("/assistencia", ensureAuthenticated, ensurePermissions(["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"]), asyncHandler(controller.obterAssistencia.bind(controller)));
dashboardRoutes.get("/power-bi", ensureAuthenticated, ensurePermissions(["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"]), asyncHandler(controller.obterPowerBi.bind(controller)));
dashboardRoutes.get("/power-bi/detalhamentos/:id", ensureAuthenticated, ensurePermissions(["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"]), asyncHandler(controller.obterDetalhamentoPowerBi.bind(controller)));
dashboardRoutes.get("/vulnerabilidade", ensureAuthenticated, ensurePermissions(["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"]), asyncHandler(controller.obterVulnerabilidade.bind(controller)));
dashboardRoutes.post("/vulnerabilidade/geocodificar-pendentes", ensureAuthenticated, ensurePermissions(["ADMINISTRADOR", "OPERADOR"]), asyncHandler(controller.geocodificarVulnerabilidade.bind(controller)));
dashboardRoutes.get("/georreferenciamento/opcoes", ensureAuthenticated, ensurePermissions(["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"]), asyncHandler(controller.listarOpcoesGeorreferenciamento.bind(controller)));
dashboardRoutes.post("/georreferenciamento/consulta", ensureAuthenticated, ensurePermissions(["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"]), asyncHandler(controller.consultarGeorreferenciamento.bind(controller)));
dashboardRoutes.get("/georreferenciamento/detalhe/:id", ensureAuthenticated, ensurePermissions(["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"]), asyncHandler(controller.obterDetalheGeorreferenciamento.bind(controller)));
dashboardRoutes.get("/georreferenciamento/vinculos", ensureAuthenticated, ensurePermissions(["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"]), asyncHandler(controller.buscarVinculosGeorreferenciamento.bind(controller)));
dashboardRoutes.post("/georreferenciamento/marcacoes", ensureAuthenticated, ensurePermissions(["ADMINISTRADOR", "OPERADOR"]), asyncHandler(controller.salvarMarcacaoGeorreferenciamento.bind(controller)));
dashboardRoutes.post("/georreferenciamento/geocodificar-pendentes", ensureAuthenticated, ensurePermissions(["ADMINISTRADOR", "OPERADOR"]), asyncHandler(controller.geocodificarGeorreferenciamento.bind(controller)));
